", "months": 6, "image": null, "description": "Beauty basics: skincare, makeup and facial treatments with salon practice.", "modules": [{"name": "Introduction to Beauty and Skincare", "chapters": ["Skin Types & Analysis", "Cleansing, Toning & Moisturising", "Beauty Products & Tools", "Hygiene & Sanitation"]}, {"name": "Makeup Application and Techniques", "chapters": ["Makeup Tools & Products", "Base: Primer, Foundation & Concealer", "Eye & Lip Makeup", "Day, Party & Bridal Makeup"]}, {"name": "Facial Treatments and Techniques", "chapters": ["Facial Steps & Massage", "Facials for Skin Types", "Bleach & Clean-up", "Threading & Waxing"]}, {"name": "Assignment & Project Work", "chapters": ["Module-wise Assignments", "Practical Record File", "Project Planning", "Project Work", "Project Report & Presentation", "Viva"]}]}, {"code": "ADBC", "name": "Advance Diploma in Beautician Course", "category": "SKILL_DEVELOPMENT", "months": 12, "image": null, "description": "One-year beautician course: skincare, makeup, facials, hair, nails and salon health and safety.", "modules": [{"name": "Introduction to Beauty and Skincare", "chapters": ["Skin Types & Analysis", "Cleansing, Toning & Moisturising", "Beauty Products & Tools", "Hygiene & Sanitation"]}, {"name": "Makeup Application and Techniques", "chapters": ["Makeup Tools & Products", "Base Makeup", "Eye & Lip Makeup", "Party & Bridal Makeup", "HD & Airbrush Basics"]}, {"name": "Facial Treatments and Techniques", "chapters": ["Facial Steps & Massage", "Facials for Skin Types", "Bleach & Clean-up", "Threading & Waxing"]}, {"name": "Hair Care and Styling Techniques", "chapters": ["Hair Types & Scalp Care", "Hair Cuts", "Blow-dry & Styling", "Hair Colour", "Hair Spa & Treatments"]}, {"name": "Nail Care and Manicures / Pedicures", "chapters": ["Nail Anatomy & Care", "Manicure", "Pedicure", "Nail Art & Extensions"]}, {"name": "Health and Safety in the Beauty Salon", "chapters": ["Salon Hygiene & Sterilisation", "Allergy & Patch Tests", "Client Handling", "Running a Salon"]}, {"name": "Assignment & Project Work", "chapters": ["Module-wise Assignments", "Practical Record File", "Project Planning", "Project Work", "Project Report & Presentation", "Viva"]}]}, {"code": "DTC", "name": "Diploma in Tailoring Course", "category": "SKILL_DEVELOPMENT", "months": 6, "image": null, "description": "Tailoring trade: drafting, pattern making, fitting, alterations and advanced stitching.", "modules": [{"name": "Introduction to Tailoring", "chapters": ["Sewing Machine Parts & Care", "Tools & Equipment", "Fabrics & Measurement", "Basic Hand & Machine Stitches"]}, {"name": "Drafting and Pattern Making", "chapters": ["Taking Body Measurements", "Drafting Basics", "Blouse Pattern", "Salwar-Kameez Pattern", "Shirt & Trouser Pattern"]}, {"name": "Fitting and Alterations", "chapters": ["Checking the Fit", "Common Fitting Problems", "Alterations: Loosening & Tightening", "Hemming & Finishing"]}, {"name": "Advance Tailoring Skills", "chapters": ["Designer Blouses", "Kurtis & Gowns", "Kids' Garments", "Embroidery & Decoration", "Costing & Running a Tailoring Shop"]}, {"name": "Assignment & Project Work", "chapters": ["Module-wise Assignments", "Practical Record File", "Project Planning", "Project Work", "Project Report & Presentation", "Viva"]}]}]$J$;
  c        jsonb;
  m        jsonb;
  ch       jsonb;
  v_org    text := public.website_organization();
  v_course text;
  v_mod    text;
  i        int;
  j        int;
  v_names  text[];
  v_subj   boolean;
begin
  for c in select value from jsonb_array_elements(d) loop
    select "id" into v_course from public.courses
     where upper("code") = c->>'code' and "deletedAt" is null limit 1;

    if v_course is null then
      insert into public.courses ("organizationId", "name", "code", "category", "description",
                                  "durationValue", "durationUnit", "baseFee", "image", "showOnWebsite", "isActive", "updatedAt")
      values (v_org, c->>'name', c->>'code', c->>'category', c->>'description',
              (c->>'months')::int, 'MONTHS', 0, nullif(c->>'image', ''), true, true, now())
      returning "id" into v_course;
    else
      update public.courses
         set "name" = c->>'name',
             "description" = c->>'description',
             "durationValue" = (c->>'months')::int,
             "websitePage" = case when c->>'code' = 'DCA' then null else "websitePage" end,
             "isActive" = true,
             "showOnWebsite" = true,
             "updatedAt" = now()
       where "id" = v_course;
    end if;

    -- Modules the proposal no longer lists are retired with their chapters.
    select array_agg(value->>'name') into v_names from jsonb_array_elements(c->'modules');
    update public.course_chapters set "deletedAt" = now()
     where "deletedAt" is null and "moduleId" in (
       select "id" from public.course_modules
        where "courseId" = v_course and "deletedAt" is null and not ("name" = any (v_names)));
    update public.course_modules set "deletedAt" = now()
     where "courseId" = v_course and "deletedAt" is null and not ("name" = any (v_names));

    v_subj := exists (select 1 from public.course_subjects where "courseId" = v_course and "deletedAt" is null);

    i := 0;
    for m in select value from jsonb_array_elements(c->'modules') loop
      i := i + 1;
      select "id" into v_mod from public.course_modules
       where "courseId" = v_course and "name" = m->>'name' and "deletedAt" is null limit 1;
      if v_mod is null then
        insert into public.course_modules ("courseId", "name", "sortOrder")
        values (v_course, m->>'name', i) returning "id" into v_mod;
        j := 0;
        for ch in select value from jsonb_array_elements(m->'chapters') loop
          j := j + 1;
          insert into public.course_chapters ("moduleId", "courseId", "name", "sortOrder")
          values (v_mod, v_course, ch #>> '{}', j);
        end loop;
      else
        update public.course_modules set "sortOrder" = i, "updatedAt" = now() where "id" = v_mod;
      end if;

      if not v_subj then
        if (m->>'name') ~* '(practical|project|assignment)' then
          insert into public.course_subjects ("courseId", "term", "code", "name", "subjectType",
                                              "theoryMax", "theoryMin", "practicalMax", "practicalMin", "sortOrder")
          values (v_course, 1, (c->>'code') || '-' || lpad(i::text, 2, '0'), m->>'name', 'PRACTICAL', 0, 0, 100, 33, i);
        else
          insert into public.course_subjects ("courseId", "term", "code", "name", "subjectType",
                                              "theoryMax", "theoryMin", "practicalMax", "practicalMin", "sortOrder")
          values (v_course, 1, (c->>'code') || '-' || lpad(i::text, 2, '0'), m->>'name', 'THEORY', 100, 33, 0, 0, i);
        end if;
      end if;
    end loop;

    -- Offered at every live branch, so a centre can admit into it straight away.
    insert into public.branch_courses ("branchId", "courseId", "isOffered")
    select b."id", v_course, true
      from public.branches b
     where b."organizationId" = v_org and b."deletedAt" is null
       and not exists (select 1 from public.branch_courses bc where bc."branchId" = b."id" and bc."courseId" = v_course);
  end loop;
end
$seed$;

select count(*) filter (where "deletedAt" is null) as courses,
       (select count(*) from public.course_modules where "deletedAt" is null) as modules,
       (select count(*) from public.course_chapters where "deletedAt" is null) as chapters,
       (select count(*) from public.course_subjects where "deletedAt" is null) as subjects,
       jsonb_array_length(public.public_courses()) as on_website
  from public.courses;
